import{_ as t,o,c as n,a0 as a}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"Handoffs","description":"Where each handoff setting comes from, model discovery, and repository resolution.","frontmatter":{"title":"Handoffs","description":"Where each handoff setting comes from, model discovery, and repository resolution."},"headers":[],"relativePath":"work-flow/handoffs.md","filePath":"work-flow/handoffs.md"}'),s={name:"work-flow/handoffs.md"};function r(i,e,h,d,l,f){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="handoffs" tabindex="-1">Handoffs <a class="header-anchor" href="#handoffs" aria-label="Permalink to &quot;Handoffs&quot;">​</a></h1><p>Enter on an open ticket starts a handoff with the settings its task type resolves. The override panel changes them for that one handoff only; it never becomes a default. A workflow handoff resolves the next task type&#39;s own settings and inherits nothing from the previous handoff, and <code>e</code> on its decision row edits the resolved settings first. A Restart repeats the interrupted handoff&#39;s settings, because that handoff is the decision being resumed.</p><p>Each setting resolves on its own chain, closest to the handoff first:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where it comes from, in order</th></tr></thead><tbody><tr><td>Agent</td><td>Your override, then the transition&#39;s pin, then the task type&#39;s, then the default agent</td></tr><tr><td>Model</td><td>Your override, then the task type&#39;s, then the default model, then the agent&#39;s own default</td></tr><tr><td>Thinking level</td><td>Your override, then the task type&#39;s, then the agent&#39;s own default</td></tr><tr><td>Context window</td><td>Your override, then the task type&#39;s, then the agent&#39;s own default</td></tr><tr><td>Environment</td><td>Your override, then the transition&#39;s pin, then the default environment</td></tr></tbody></table><p>A handoff that resolves a value the chosen agent cannot take fails before anything starts, with a readable reason, and the ticket stays where it was. So a model written for one agent never runs a different one quietly, and a route onto a narrower agent is seen as a failure instead of being absorbed as a default.</p><h2 id="model-discovery" tabindex="-1">Model discovery <a class="header-anchor" href="#model-discovery" aria-label="Permalink to &quot;Model discovery&quot;">​</a></h2><p>The agent CLI owns the list of models it can run, and the config file names no models. The control plane queries the agent on demand and keeps no cache: the list is what the agent reports this moment, so you can change a provider&#39;s auth while the plane runs. That is why a model you wrote passes or fails. At startup, a config that names a model its agent does not offer stops the start with a readable line per value; at a handoff, a model not on the agent&#39;s current list fails it before it changes anything outside the control plane. A list that cannot be fetched only warns, so one agent that cannot answer does not block the control plane, and the agent&#39;s own rejection stands. An agent whose CLI reports no list takes a free-text model value instead, and those values are not checked.</p><h2 id="repository-resolution" tabindex="-1">Repository resolution <a class="header-anchor" href="#repository-resolution" aria-label="Permalink to &quot;Repository resolution&quot;">​</a></h2><p>The control plane finds the ticket&#39;s repository in this order:</p><ol><li>The mapping in your config: <code>[repos] &quot;github.com/owner/name&quot; = &quot;/path&quot;</code>. The path must hold a checkout of exactly that repository - the remote is matched by repository, not by URL shape, so https and ssh, a port, and other spellings all count. A mismatch is a hard failure: the control plane never uses the wrong tree.</li><li>The convention path <code>~/src/&lt;repository name&gt;</code>.</li></ol><p>When the convention path holds a different repository, the control plane clones the ticket&#39;s repository to a sibling path (for example <code>~/src/billing_1</code>), hands off there, warns on the Message line, and hands the new mapping back to be written to your config file, so the next handoff resolves it explicitly. <a href="./../configuration/">The Configuration page</a> carries the <code>[repos]</code> key.</p>',11)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
